// Meme phrases: plays a clip's audio and hands the renderer the matching frame of the pixelated talking face.
// The clip table and the face rectangle come from src/phrase-clips.mjs (generated by tools/make_phrases.py).
import { CLIP_FPS, FACE_RECT, PHRASE_CLIPS } from './phrase-clips.mjs';

/** Draws items in a shuffled order, never the same one twice in a row (also across reshuffles). */
export class ShuffleBag {
  constructor(items, random = Math.random) {
    this.items = [...items];
    this.random = random;
    this.queue = [];
    this.last = null;
  }

  next() {
    if (this.items.length === 0) return null;
    if (this.queue.length === 0) this.queue = this.#shuffled();
    const item = this.queue.shift();
    this.last = item;
    return item;
  }

  #shuffled() {
    const order = [...this.items];
    for (let i = order.length - 1; i > 0; i--) {
      const j = Math.floor(this.random() * (i + 1));
      [order[i], order[j]] = [order[j], order[i]];
    }
    if (order.length > 1 && order[0] === this.last) [order[0], order[1]] = [order[1], order[0]];
    return order;
  }
}

/** Index of the face frame at `seconds` into a clip, or -1 once the clip is over. */
export function frameAt(seconds, frames, fps = CLIP_FPS) {
  if (!(seconds >= 0)) return 0;
  const index = Math.floor(seconds * fps);
  return index < frames ? index : -1;
}

/** What the renderer needs to draw frame `index` of a loaded clip over the mascot's face. */
export const faceFrame = (clip, index) => (
  { image: clip.sheet, sx: index * FACE_RECT.w, sy: 0, sw: FACE_RECT.w, sh: FACE_RECT.h, rect: FACE_RECT }
);

/** Loads every clip (sheet + audio) and plays one at a time. */
export class PhrasePlayer {
  /** @param clock () => seconds; @param baseUrl folder with <key>.png and <key>.ogg */
  constructor(clock, baseUrl) {
    this.clock = clock;
    this.baseUrl = baseUrl;
    this.clips = [];
    this.current = null;            // { clip, startedAt }
  }

  /** Loads what it can; a clip whose sheet fails is left out and reported, the rest still play. */
  async load() {
    const results = await Promise.allSettled(PHRASE_CLIPS.map((clip) => this.#loadClip(clip)));
    results.forEach((r, i) => {
      if (r.status === 'rejected') console.error(`Phrase "${PHRASE_CLIPS[i].key}" failed to load`, r.reason);
    });
    this.clips = results.filter((r) => r.status === 'fulfilled').map((r) => r.value);
    return this.clips;
  }

  async #loadClip(clip) {
    const sheet = new Image();
    sheet.src = `${this.baseUrl}/${clip.key}.png`;
    await sheet.decode();
    const audio = new Audio(`${this.baseUrl}/${clip.key}.ogg`);
    audio.preload = 'auto';
    return { ...clip, sheet, audio };
  }

  /** The loaded clip with this key, or null. */
  clip(key) { return this.clips.find((c) => c.key === key) ?? null; }

  /** True while a clip is still running (its audio or, if the audio failed, its frames). */
  get isTalking() { return this.current !== null && this.#elapsed() !== null; }

  /** Starts `clip` from the top, cutting off whatever was playing. */
  play(clip) {
    this.stop();
    clip.audio.currentTime = 0;
    clip.audio.play().catch((err) => console.error(`Phrase "${clip.key}" audio did not play`, err));
    this.current = { clip, startedAt: this.clock() };
  }

  stop() {
    if (!this.current) return;
    this.current.clip.audio.pause();
    this.current = null;
  }

  /** Seconds into the current clip, following the audio while it plays so the mouth stays in sync. */
  #elapsed() {
    const { clip, startedAt } = this.current;
    const audio = clip.audio;
    const t = !audio.paused && audio.currentTime > 0 ? audio.currentTime : this.clock() - startedAt;
    return frameAt(t, clip.frames) < 0 ? null : t;
  }

  /** The face to draw this frame: { image, sx, sy, sw, sh, rect } or null when nothing is playing. */
  face() {
    if (!this.current) return null;
    const t = this.#elapsed();
    if (t === null) { this.current = null; return null; }
    const { clip } = this.current;
    return faceFrame(clip, frameAt(t, clip.frames));
  }
}
